#!/usr/bin/env python3
import csv
import heapq
import json
import math
from collections import defaultdict
from pathlib import Path

import numpy as np
from Bio import SeqIO
from scipy.spatial import cKDTree

INPUT = Path('/task/input')
OUTPUT = Path('/task/output')
LIMIT = 34.0
TETHER = 7.0
EPS = 1e-10
THREE_TO_ONE = {
    'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q',
    'GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K',
    'MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W',
    'TYR':'Y','VAL':'V','MSE':'M','SEC':'U','PYL':'O',
}
OFFSETS = tuple(
    (dx, dy, dz)
    for dx in (-1, 0, 1)
    for dy in (-1, 0, 1)
    for dz in (-1, 0, 1)
    if (dx, dy, dz) != (0, 0, 0)
)


def read_models(path):
    """Return chain metadata, CA coordinates, and all non-H atom coordinates."""
    residues = defaultdict(dict)
    ca = {}
    atom_xyz = []
    with open(path) as fh:
        for line in fh:
            if not line.startswith(('ATOM  ', 'HETATM')):
                continue
            element = line[76:78].strip().upper()
            if element in ('H', 'D'):
                continue
            xyz = np.array((float(line[30:38]), float(line[38:46]),
                            float(line[46:54])), dtype=float)
            atom_xyz.append(xyz)
            chain = line[21].strip()
            resnum = int(line[22:26])
            residues[chain][resnum] = THREE_TO_ONE.get(line[17:20].strip(), 'X')
            if line[12:16].strip() == 'CA':
                ca[(chain, resnum)] = xyz
    chains = {}
    for chain, rr in residues.items():
        nums = sorted(rr)
        chains[chain] = {
            'resnums': nums,
            'sequence': ''.join(rr[n] for n in nums),
            'ca': {n: ca[(chain, n)] for n in nums},
        }
    return chains, ca, np.asarray(atom_xyz, dtype=float)


def assign_constructs(chains, full_sequences):
    """Assign each chain an accession and a 1-based full-position map."""
    assignments = {}
    for chain, info in chains.items():
        hits = []
        for accession, full in full_sequences.items():
            start0 = full.find(info['sequence'])
            if start0 >= 0:
                # A construct should occur once; also reject ambiguous repeated hits.
                if full.find(info['sequence'], start0 + 1) >= 0:
                    continue
                hits.append((accession, start0 + 1))
        if len(hits) != 1:
            raise RuntimeError(f'Could not uniquely assign chain {chain}: {hits}')
        accession, full_start = hits[0]
        nums = info['resnums']
        if nums != list(range(nums[0], nums[-1] + 1)):
            raise RuntimeError(f'Non-contiguous residue numbering in chain {chain}')
        # All observed PDB numbers here begin at 1. Position i of the construct
        # corresponds to full_start + (i - 1).
        if nums[0] != 1:
            raise RuntimeError(f'Unexpected construct numbering in chain {chain}: {nums[0]}')
        posmap = {full_start + i - 1: i for i in nums}
        assignments[chain] = {
            'accession': accession,
            'full_start': full_start,
            'full_end': full_start + len(nums) - 1,
            'position_to_resnum': posmap,
            'resnum_to_position': {v: k for k, v in posmap.items()},
        }
    counts = defaultdict(int)
    for a in assignments.values():
        counts[a['accession']] += 1
    if set(counts.values()) != {2}:
        raise RuntimeError(f'Expected two copies of each accession: {dict(counts)}')
    return assignments


class SurfaceDistance:
    """Exact thresholded A* on the weighted integer-lattice graph."""
    def __init__(self, atoms):
        self.tree = cKDTree(atoms)
        self.open_cache = {}

    def _open_points(self, points):
        points = np.asarray(points, dtype=float)
        keys = [tuple(int(v) for v in p) for p in points]
        missing = [i for i, k in enumerate(keys) if k not in self.open_cache]
        if missing:
            distances, _ = self.tree.query(points[missing], k=1)
            for i, distance in zip(missing, distances):
                # A point is blocked iff its distance is strictly less than 3 A.
                self.open_cache[keys[i]] = bool(distance >= 3.0 - 1e-12)
        return [self.open_cache[k] for k in keys]

    @staticmethod
    def _lattice_in_sphere(center, radius=TETHER):
        lo = np.floor(center - radius - 1e-12).astype(int)
        hi = np.ceil(center + radius + 1e-12).astype(int)
        axes = [np.arange(lo[i], hi[i] + 1) for i in range(3)]
        grid = np.array(np.meshgrid(*axes, indexing='ij')).reshape(3, -1).T
        norms = np.linalg.norm(grid - center, axis=1)
        return grid[norms <= radius + 1e-10]

    def distance(self, p, q, limit=LIMIT):
        """Return the minimum surface distance, or math.inf if out of range."""
        p = np.asarray(p, dtype=float)
        q = np.asarray(q, dtype=float)
        endpoint_distance = float(np.linalg.norm(p - q))
        # Surface distance cannot be less than the straight endpoint distance.
        if endpoint_distance > limit + EPS:
            return math.inf

        starts = self._lattice_in_sphere(p)
        ends = self._lattice_in_sphere(q)
        start_open = self._open_points(starts)
        end_open = self._open_points(ends)
        starts = starts[start_open]
        ends = ends[end_open]
        if len(starts) == 0 or len(ends) == 0:
            return math.inf

        end_dist = {tuple(int(v) for v in x): float(np.linalg.norm(x - q))
                   for x in ends}
        heap = []
        best = {}
        for x in starts:
            key = tuple(int(v) for v in x)
            g = float(np.linalg.norm(x - p))       # P tether
            h = end_dist.get(key, float(np.linalg.norm(x - q)))
            if g + h > limit + EPS:
                continue
            if g < best.get(key, math.inf):
                best[key] = g
                heapq.heappush(heap, (g + h, g, key))

        while heap:
            f, g, key = heapq.heappop(heap)
            if g != best.get(key):
                continue
            if f > limit + EPS:
                break
            # At an endpoint candidate, the final tether is exactly Euclidean.
            if key in end_dist:
                total = g + end_dist[key]
                if total <= limit + EPS:
                    return total

            neighbors = []
            for dx, dy, dz in OFFSETS:
                nk = (key[0] + dx, key[1] + dy, key[2] + dz)
                neighbors.append(nk)
            open_flags = self._open_points(neighbors)
            for (dx, dy, dz), nk, is_open in zip(OFFSETS, neighbors, open_flags):
                if not is_open:
                    continue
                ng = g + math.sqrt(dx*dx + dy*dy + dz*dz)
                if ng >= best.get(nk, math.inf):
                    continue
                nh = end_dist.get(nk, float(np.linalg.norm(np.asarray(nk) - q)))
                # Euclidean distance to Q is an admissible lower bound.
                if ng + nh > limit + EPS:
                    continue
                best[nk] = ng
                heapq.heappush(heap, (ng + nh, ng, nk))
        return math.inf


def main():
    OUTPUT.mkdir(parents=True, exist_ok=True)
    full_sequences = {record.id: str(record.seq)
                      for record in SeqIO.parse(INPUT / 'sequences.fasta', 'fasta')}
    with open(INPUT / 'crosslinks.csv', newline='') as fh:
        links = list(csv.DictReader(fh))
    for row in links:
        row['position_a'] = int(row['position_a'])
        row['position_b'] = int(row['position_b'])

    model_paths = sorted((INPUT / 'models').glob('model_*.pdb'))
    if len(model_paths) != 17:
        raise RuntimeError(f'Expected 17 models, found {len(model_paths)}')

    # Parse and validate every model first.
    model_data = {}
    for path in model_paths:
        name = path.stem
        chains, ca, atoms = read_models(path)
        assignments = assign_constructs(chains, full_sequences)
        model_data[name] = {
            'path': path,
            'chains': chains,
            'assignments': assignments,
            'ca': ca,
            'atoms': atoms,
        }

    # Required mapping.tsv is based specifically on model_01.
    model1 = model_data['model_01']
    chains_by_acc = defaultdict(list)
    for chain, ainfo in model1['assignments'].items():
        chains_by_acc[ainfo['accession']].append(chain)
    for chains in chains_by_acc.values():
        chains.sort()
    distinct_positions = set()
    for row in links:
        distinct_positions.add((row['protein_a'], row['position_a']))
        distinct_positions.add((row['protein_b'], row['position_b']))
    with open(OUTPUT / 'mapping.tsv', 'w', newline='') as fh:
        writer = csv.writer(fh, delimiter='\t', lineterminator='\n')
        writer.writerow(['accession', 'position', 'model_chain', 'model_resnum'])
        for accession, position in sorted(distinct_positions):
            chains = chains_by_acc.get(accession, [])
            ainfo = model1['assignments'][chains[0]] if chains else None
            if ainfo and position in ainfo['position_to_resnum']:
                resnum = ainfo['position_to_resnum'][position]
                writer.writerow([accession, position, ','.join(chains), resnum])
            else:
                writer.writerow([accession, position, 'NA', 'NA'])

    restraints = []
    statuses = []
    diagnostic = []
    for name in sorted(model_data):
        data = model_data[name]
        evaluator = SurfaceDistance(data['atoms'])
        distance_cache = {}
        inter_sat = inter_total = intra_sat = intra_total = 0
        for row in links:
            acc_a, acc_b = row['protein_a'], row['protein_b']
            pos_a, pos_b = row['position_a'], row['position_b']
            is_inter = acc_a != acc_b

            chains_a = [ch for ch, ai in data['assignments'].items()
                        if ai['accession'] == acc_a and pos_a in ai['position_to_resnum']]
            chains_b = [ch for ch, ai in data['assignments'].items()
                        if ai['accession'] == acc_b and pos_b in ai['position_to_resnum']]
            if not chains_a or not chains_b:
                status = 'not_evaluable'
            else:
                if is_inter:
                    inter_total += 1
                else:
                    intra_total += 1
                assignments_to_test = []
                for cha in chains_a:
                    for chb in chains_b:
                        if acc_a == acc_b and pos_a == pos_b and cha == chb:
                            continue
                        assignments_to_test.append((cha, chb))
                satisfied = False
                min_distance = math.inf
                for cha, chb in assignments_to_test:
                    rna = data['assignments'][cha]['position_to_resnum'][pos_a]
                    rnb = data['assignments'][chb]['position_to_resnum'][pos_b]
                    pair = tuple(sorted(((cha, rna), (chb, rnb))))
                    if pair not in distance_cache:
                        p = data['ca'][(cha, rna)]
                        q = data['ca'][(chb, rnb)]
                        distance_cache[pair] = evaluator.distance(p, q)
                    distance = distance_cache[pair]
                    min_distance = min(min_distance, distance)
                    if distance <= LIMIT + EPS:
                        satisfied = True
                status = 'satisfied' if satisfied else 'violated'
                if satisfied:
                    if is_inter:
                        inter_sat += 1
                    else:
                        intra_sat += 1
            statuses.append((name, row['xl_id'], status))
            diagnostic.append((name, row['xl_id'], 'inter' if is_inter else 'intra',
