        writer = csv.writer(fh, delimiter='\t', lineterminator='\n')
        writer.writerow(['model', 'xl_id', 'status'])
        writer.writerows(statuses)

    total_by_model = {r[0]: r[1] + r[3] for r in restraints}
    ranking = sorted(total_by_model, key=lambda m: (-total_by_model[m], m))
    selection = {'best_model': ranking[0], 'ranking': ranking}
    with open(OUTPUT / 'selection.json', 'w') as fh:
        json.dump(selection, fh, indent=2)
        fh.write('\n')

    with open('/tmp/xlms_diagnostics.tsv', 'w', newline='') as fh:
        writer = csv.writer(fh, delimiter='\t', lineterminator='\n')
        writer.writerow(['model', 'xl_id', 'class', 'status', 'minimum_surface_distance'])
        for row in diagnostic:
            writer.writerow(row[:-1] + [('inf' if math.isinf(row[-1]) else f'{row[-1]:.6f}')])

    print('Ranking and totals:')
    for model in ranking:
        r = next(x for x in restraints if x[0] == model)
        print(model, 'inter', f'{r[1]}/{r[2]}', 'intra', f'{r[3]}/{r[4]}',
              'total', r[1] + r[3])


if __name__ == '__main__':
    main()
