 ax=[np.arange(lo[i],hi[i]+1) for i in range(3)]
 g=np.array(np.meshgrid(*ax,indexing='ij')).reshape(3,-1).T
 return g[np.linalg.norm(g-x,axis=1)<=r+1e-10]

def parse(p):
